xml.Script:
        clLime := '72AF11';
        clTeal := '3299A7';

        clWhite := 'FFFFFF';
        clBlack  := '333333';

        K := 0.6;

        R1 := 0.2;
        R2 := 0.42;

        C := 5;
        N := 40;
        for i := 0 to N - 1 do begin
            A := 2*Pi / N * i;
            sa := sin(A);
            ca := cos(A);
            x1[i] := R1 * ca;
            y1[i] := R1 * sa;
            x2[i] := R2 * ca;
            y2[i] := R2 * sa;
        end;

        D2 := K * 0.71029864124335; 
        D1 := (D2 + y2[2]) / sqrt(2);

        H := D2 + y2[2] + y1[6];
        m := (y1[2] - y2[2]) / (H - D2);

        D3 := (sqrt(2) * D1 + y2[2] - m * D2) / (1 - m);

        D4 := D1 - K * 0.2;
        D5 := D2 - K * 0.2;


        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

